suppressPackageStartupMessages(library(data.table));setDTthreads(4)
BASE='almanac_conditionals/state_conditioned_bridge/program_first';OUT=file.path(BASE,'results');ART=file.path(BASE,'artifacts');inp=readRDS(file.path(ART,'y_discovery_inputs.rds'));genes=inp$genes
write_npy=function(X,path){stopifnot(is.matrix(X));h=sprintf("{'descr': '<f8', 'fortran_order': True, 'shape': (%d, %d), }",nrow(X),ncol(X));pad=(64-(10+nchar(h)+1)%%64)%%64;h=paste0(h,strrep(' ',pad),'\n');con=file(path,'wb');on.exit(close(con));writeBin(charToRaw('\x93NUMPY'),con);writeBin(as.raw(c(1,0)),con);writeBin(as.integer(nchar(h)),con,size=2,endian='little');writeBin(charToRaw(h),con);writeBin(as.numeric(X),con,size=8,endian='little')}
cy=fread('data/01_CytoSig_data/diff.merge.gz',showProgress=F);setnames(cy,1,'gene');X=as.matrix(cy[match(genes,gene),-1]);rownames(X)=genes;rm(cy)
cm0=fread('data/01_CytoSig_data/meta_info.txt',skip=1,header=F,col.names=c('profile_id','treatment','condition','duration','dose'));cm=merge(data.table(profile_id=colnames(X)),cm0,by='profile_id',all.x=T,sort=F)[match(colnames(X),profile_id)];excluded=apply(cm,1,function(z)any(grepl('AU[ _-]?565|ACH-000248',z,ignore.case=T)));fwrite(cm[excluded],file.path(OUT,'excluded_wilson_cytosig_profiles.tsv'),sep='\t');cm=cm[!excluded];X=X[,!excluded,drop=F];cm[is.na(treatment)|!nzchar(treatment),treatment:=sub('[&@].*','',profile_id)];cm[,study:=sub('.*@((?:GSE[0-9]+|E-(?:MTAB|MEXP|TABM|SGRP)-[0-9]+)).*','\\1',profile_id,perl=T)];cm[!grepl('^(GSE[0-9]+|E-(?:MTAB|MEXP|TABM|SGRP)-[0-9]+)$',study),study:=paste0('independent_',.I)];counts=table(cm$study);w=1/as.numeric(counts[cm$study]);w=w/sum(w)
inp$cyto_all=X;inp$cyto_meta_all=cm;saveRDS(inp,file.path(ART,'y_discovery_inputs.rds'));X=sweep(X,2,colMeans(X,na.rm=T),'-');R=t(apply(X,1,rank,na.last='keep',ties.method='average'));Z=t(R);rm(R,X);gc();M=is.finite(Z);cat('CytoSig: ',ncol(Z),' genes; ',nrow(Z),' profiles; missing ',sum(!M),'\n',sep='');Z[!M]=0
# Weighted rank correlation; algebraically identical to original pairwise centering.
if(all(M)){mu=colSums(Z*w);Z=sweep(Z,2,mu,'-');C=crossprod(Z*sqrt(w));v=sqrt(pmax(diag(C),1e-30));C=C/outer(v,v)}else{den=crossprod(M*sqrt(w));S=crossprod(Z*w,M);A=crossprod(Z^2*w,M);C=crossprod(Z*sqrt(w))-S*t(S)/den;A=A-S^2/den;C=C/sqrt(pmax(A,0)*pmax(t(A),0));C[!is.finite(C)]=0};diag(C)=1;C=pmax(pmin(C,1),-1);dimnames(C)=list(genes,genes)
# Verify exact pairwise calculation, including missing values, before persisting.
set.seed(20260928);checks=lapply(1:100,function(i){ij=sample(ncol(Z),2);ok=M[,ij[1]]&M[,ij[2]];ww=w[ok]/sum(w[ok]);a=Z[ok,ij[1]];b=Z[ok,ij[2]];a=a-sum(ww*a);b=b-sum(ww*b);d=sqrt(sum(ww*a*a)*sum(ww*b*b));r=if(d>0)sum(ww*a*b)/d else 0;data.table(gene1=genes[ij[1]],gene2=genes[ij[2]],error=abs(r-C[ij[1],ij[2]]))});checks=rbindlist(checks);stopifnot(max(checks$error)<1e-10,all(is.finite(C)));fwrite(checks,file.path(OUT,'cytosig_correlation_identity.tsv'),sep='\t');write_npy(C,file.path(ART,'discovery_cytosig_correlation.npy'));fwrite(cm,file.path(OUT,'cytosig_discovery_metadata.tsv'),sep='\t');cat('Saved exact weighted CytoSig Spearman correlation\n')
